import { mount } from '@vue/test-utils'
import { afterEach, describe, expect, it } from 'vitest'
import type { RouteRecordRaw } from 'vue-router'
import AppBreadcrumb from '../../src/layouts/components/AppBreadcrumb.vue'
import { createStubbedRouter, flattenRoutes, routeId } from './router.helper'
import type { I18nLike } from './menu.helper'

/**
 * Checks that the page header of EVERY route of a product is localized.
 *
 * Pages get their header from the route: `meta.title` and `meta.breadcrumb` (generated by
 * `sectionRouterGenerator` from the product's `additional-routes.ts`). `AppBreadcrumb` renders them as
 * `$t('title.<key>')`. A missing key does not throw — the header silently shows the raw `title.some-key`.
 *
 * Mounts the REAL `AppBreadcrumb` on a router built from the product's REAL routes, navigates to each
 * route and reads what is on screen, so a new section is covered the moment its route exists.
 */

/** Raw `title.some.key` left in the rendered text means the key was not translated. */
const RAW_TITLE_KEY = /\btitle\.[\w.-]+/g

/** `/:project/games/categories/update/:id` → `{ project: 'alpha', id: '1' }`; optional params are skipped */
const paramsFor = (path: string) =>
  Object.fromEntries(
    [...path.matchAll(/:(\w+)(\?)?/g)]
      .filter(([, , optional]) => !optional)
      .map(([, param]) => [param, param === 'project' ? 'alpha' : '1']),
  )

const hasHeader = ({ name, meta }: RouteRecordRaw) => !!name && !!(meta?.title || meta?.breadcrumb)

export interface RouteBreadcrumbsOptions {

  /** The product's routes, e.g. `routes` from `plugins/2.router/additional-routes.ts`. */
  routes: RouteRecordRaw[]

  /** The product's i18n (`src/plugins/i18n`) — it holds the product's own messages, the core's copy does not. */
  i18n: I18nLike

  /**
   * Routes whose header is untranslated today, by route name — a frozen baseline, so the check guards
   * against NEW misses. Fix the key, then delete the entry (a fixed route listed here fails).
   */
  knownUntranslated?: string[]

  /**
   * Routes that have no header on purpose (login, error pages, the catch-all), by `routeId`. Every other
   * route must have `meta.title` or `meta.breadcrumb`, otherwise its header silently does not render.
   */
  headerless?: string[]

  /** Narrow the check, e.g. to list routes only: `route => String(route.name).endsWith('List')`. */
  filter?: (route: RouteRecordRaw) => boolean
}

export const describeRouteBreadcrumbs = ({
  routes: productRoutes,
  i18n,
  knownUntranslated = [],
  headerless = [],
  filter = () => true,
}: RouteBreadcrumbsOptions) => {
  describe('page header (AppBreadcrumb) of every route', () => {
    const allRoutes = flattenRoutes(productRoutes)
    const wrappers: ReturnType<typeof mount>[] = []

    // AppBreadcrumb starts a UTC clock on mount
    afterEach(() => {
      wrappers.splice(0).forEach(wrapper => wrapper.unmount())
    })

    const inspect = async (route: RouteRecordRaw) => {
      const router = createStubbedRouter(productRoutes)

      await router.push({ name: route.name, params: paramsFor(route.path) })
      await router.isReady()

      const wrapper = mount(AppBreadcrumb, { global: { plugins: [router] } })

      wrappers.push(wrapper)

      const title = wrapper.find('.breadcrumb-title').text()
      const crumbs = wrapper.findAll('.v-breadcrumbs-item').map(item => item.text())

      return { title, crumbs, raw: [title, ...crumbs].flatMap(text => text.match(RAW_TITLE_KEY) ?? []) }
    }

    const routes = allRoutes.filter(hasHeader).filter(filter)
    const named = (names: string[]) => routes.filter(route => names.includes(String(route.name))).map(route => [String(route.name), route] as const)
    const rest = routes.filter(route => !knownUntranslated.includes(String(route.name))).map(route => [String(route.name), route] as const)

    it('every route either has a header or is listed as headerless', () => {
      const unexpected = allRoutes.filter(route => !hasHeader(route) && !headerless.includes(routeId(route))).map(routeId)
      const stale = headerless.filter(id => !allRoutes.some(route => routeId(route) === id && !hasHeader(route)))

      expect(unexpected, 'routes without meta.title / meta.breadcrumb (add the header or list them as headerless)').toEqual([])
      expect(stale, 'headerless entries that have a header now or no longer exist').toEqual([])
    })

    it('finds the routes (the check itself is not vacuous)', () => {
      expect(routes.length, 'routes with a header').toBeGreaterThan(0)
      expect(named(knownUntranslated).length, 'knownUntranslated names a route that does not exist').toBe(knownUntranslated.length)
    })

    it.each(rest)('%s: title and every breadcrumb are translated', async (_, route) => {
      const { title, crumbs, raw } = await inspect(route)

      expect(raw, 'untranslated keys shown in the header').toEqual([])
      expect(crumbs.length, 'breadcrumbs: home + route crumbs').toBeGreaterThan(0)

      if (route.meta?.title)
        expect(title).toBe(i18n.t(`title.${route.meta.title}`))
    })

    it.each(named(knownUntranslated))('%s is still untranslated (remove it from knownUntranslated once fixed)', async (_, route) => {
      expect((await inspect(route)).raw.length).toBeGreaterThan(0)
    })
  })
}
